using AppCondominio.Contracts.Security;using AppCondominio.Modules.Governance.Application;using AppCondominio.Modules.Governance.Domain;using Microsoft.AspNetCore.Builder;using Microsoft.AspNetCore.Http;using Microsoft.AspNetCore.Routing;
namespace AppCondominio.Modules.Governance.Api;
public static class GovernanceEndpoints
{
 public static IEndpointRouteBuilder MapGovernanceEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/governance").RequireAuthorization();g.MapPost("/assemblies",async(CreateAssemblyRequest r,GovernanceService s,CancellationToken ct)=>Results.Ok(new{Id=await s.CreateAssemblyAsync(r.CommunityId,r.Title,r.ScheduledAt,r.QuorumPercent,ct)})).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapPost("/assemblies/{id:guid}/open",async(Guid id,OpenAssemblyRequest r,GovernanceService s,CancellationToken ct)=>{await s.OpenAssemblyAsync(id,r.EligibleUnits,r.PresentUnits,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapPost("/assemblies/{id:guid}/motions",async(Guid id,CreateMotionRequest r,GovernanceService s,CancellationToken ct)=>Results.Ok(new{Id=await s.AddMotionAsync(id,r.Title,ct)})).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapPost("/motions/{id:guid}/vote",async(Guid id,VoteRequest r,GovernanceService s,CancellationToken ct)=>{await s.VoteAsync(id,r.Choice,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapPost("/motions/{id:guid}/close",async(Guid id,GovernanceService s,CancellationToken ct)=>{await s.CloseMotionAsync(id,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapPost("/assemblies/{id:guid}/close",async(Guid id,GovernanceService s,CancellationToken ct)=>{await s.CloseAssemblyAsync(id,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapPost("/coexistence-cases",async(CreateCaseRequest r,GovernanceService s,CancellationToken ct)=>Results.Ok(new{Id=await s.ReportCaseAsync(r.CommunityId,r.PropertyId,r.Category,r.Description,r.ReportedBy,ct)})).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapPost("/coexistence-cases/{id:guid}/review",async(Guid id,GovernanceService s,CancellationToken ct)=>{await s.StartReviewAsync(id,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapPost("/coexistence-cases/{id:guid}/resolve",async(Guid id,ResolveCaseRequest r,GovernanceService s,CancellationToken ct)=>{await s.ResolveCaseAsync(id,r.Resolution,r.PenaltyAmount,r.BillingReference,ct);return Results.NoContent();}).RequireAuthorization(AppCondominioPermissions.Governance.Manage);g.MapGet("/communities/{communityId:guid}/kpi",async(Guid communityId,GovernanceService s,CancellationToken ct)=>Results.Ok(await s.GetKpiAsync(communityId,ct))).RequireAuthorization(AppCondominioPermissions.Governance.Read);return app;}
}
public sealed record CreateAssemblyRequest(Guid CommunityId,string Title,DateTimeOffset ScheduledAt,decimal QuorumPercent);public sealed record OpenAssemblyRequest(int EligibleUnits,int PresentUnits);public sealed record CreateMotionRequest(string Title);public sealed record VoteRequest(VoteChoice Choice);public sealed record CreateCaseRequest(Guid CommunityId,Guid? PropertyId,string Category,string Description,string ReportedBy);public sealed record ResolveCaseRequest(string Resolution,decimal PenaltyAmount,string? BillingReference);